import { useState, type ReactNode } from 'react';
import { ArrowLeft, Blocks, Check, ChevronDown, ChevronRight, Clock3, Download, Globe, KeyRound, Monitor, MoreHorizontal, Play, Plus, RefreshCw, Search, Trash2 } from 'lucide-react';
import { Dialog, Dropdown } from './ui';
import { Group, PreferenceRow, SelectControl, Toggle, type SettingsSectionProps } from './SettingsControls';
import './integration-settings.css';

type Props = SettingsSectionProps;
const key = (name: string) => `integration.${name}`;
const value = (p: Props, name: string, fallback: string) => String(p.values[key(name)] ?? fallback);
const enabled = (p: Props, name: string, fallback = false) => Boolean(p.values[key(name)] ?? fallback);
function items<T>(p: Props, name: string, fallback: T[]): T[] {
  const raw = p.values[key(name)];
  if (typeof raw !== 'string') return fallback;
  try { const parsed: unknown = JSON.parse(raw); return Array.isArray(parsed) ? parsed as T[] : fallback; } catch { return fallback; }
}
const saveItems = <T,>(p: Props, name: string, list: T[]) => p.setValue(key(name), JSON.stringify(list));
const matches = (text: string, query: string) => text.toLocaleLowerCase().includes(query.trim().toLocaleLowerCase());
function Button({ children, onClick, disabled = false, danger = false }: { children: ReactNode; onClick: () => void; disabled?: boolean; danger?: boolean }) {
  return <button type="button" className={`settings-outline-button ${danger ? 'integration-danger' : ''}`} disabled={disabled} onClick={onClick}>{children}</button>;
}
function SearchBox({ value: query, onChange, placeholder }: { value: string; onChange: (query: string) => void; placeholder: string }) {
  return <label className="integration-search"><Search size={15} aria-hidden="true" /><input aria-label={placeholder} placeholder={placeholder} value={query} onChange={event => onChange(event.target.value)} /></label>;
}
function Empty({ children }: { children: ReactNode }) { return <div className="integration-empty">{children}</div>; }
function Note({ children = '服务尚未连接。' }: { children?: ReactNode }) { return <p className="integration-note">{children}</p>; }
function Field({ label, children }: { label: string; children: ReactNode }) { return <label className="integration-field"><span>{label}</span>{children}</label>; }
function Confirmation({ title, children, onClose, onConfirm, action = '移除' }: { title: string; children: ReactNode; onClose: () => void; onConfirm: () => void; action?: string }) {
  return <Dialog title={title} onClose={onClose} className="integration-dialog"><p className="integration-dialog-description">{children}</p><div className="integration-dialog-actions"><Button onClick={onClose}>取消</Button><Button danger onClick={onConfirm}>{action}</Button></div></Dialog>;
}
function LocalToggle({ p, name, label, description, fallback = false }: { p: Props; name: string; label: string; description?: ReactNode; fallback?: boolean }) {
  return <PreferenceRow label={label} description={description} htmlFor={key(name)}><Toggle id={key(name)} checked={enabled(p, name, fallback)} onChange={() => p.setValue(key(name), !enabled(p, name, fallback))} /></PreferenceRow>;
}
function LocalSelect({ p, name, label, description, options, fallback }: { p: Props; name: string; label: string; description?: ReactNode; options: string[]; fallback?: string }) {
  return <PreferenceRow label={label} description={description} htmlFor={key(name)}><SelectControl id={key(name)} value={value(p, name, fallback ?? options[0])} options={options} onChange={next => p.setValue(key(name), next)} /></PreferenceRow>;
}
function Back({ title, onClick }: { title: string; onClick: () => void }) { return <button className="integration-back" onClick={onClick}><ArrowLeft size={15} />{title}</button>; }

type Extension = { id: string; name: string; description: string; category: '插件' | '应用' | '技能'; enabled: boolean };
const directory: Extension[] = [
  { id: 'computer', name: 'Computer Use', description: '在你的电脑上使用应用。', category: '插件', enabled: true },
  { id: 'browser', name: 'Browser Use', description: '在浏览器中浏览并操作网页。', category: '插件', enabled: true },
  { id: 'calendar', name: '日历', description: '管理日历工具和连接。', category: '应用', enabled: true },
  { id: 'documents', name: '文档', description: '管理文档处理技能。', category: '技能', enabled: true },
];
type McpServer = { id: string; name: string; transport: string; command: string; args: string; env: string; passthrough: string; cwd: string; url: string; bearer: string; headers: string; envHeaders: string; enabled: boolean; authenticated: boolean };
const newMcp = (): McpServer => ({ id: '', name: '', transport: 'STDIO', command: '', args: '', env: '', passthrough: '', cwd: '', url: '', bearer: '', headers: '', envHeaders: '', enabled: true, authenticated: false });

function Plugins(p: Props) {
  const [tab, setTab] = useState('插件');
  const [query, setQuery] = useState('');
  const [panel, setPanel] = useState<'directory' | 'marketplace' | 'mcp' | null>(null);
  const [detail, setDetail] = useState<Extension | null>(null);
  const [remove, setRemove] = useState<{ type: 'plugin' | 'mcp' | 'market'; id: string; name: string } | null>(null);
  const [draft, setDraft] = useState(newMcp);
  const [marketName, setMarketName] = useState('');
  const [status, setStatus] = useState('');
  const installed = items<Extension>(p, 'plugins', []);
  const servers = items<McpServer>(p, 'mcps', []);
  const markets = items<{ id: string; name: string }>(p, 'markets', []);
  const setInstalled = (list: Extension[]) => saveItems(p, 'plugins', list);
  const install = (entry: Extension) => { setInstalled([...installed.filter(item => item.id !== entry.id), { ...entry, enabled: true }]); setStatus(`已添加“${entry.name}”的记录。`); };
  const field = (name: keyof McpServer, label: string, placeholder = '') => <Field label={label}><input value={String(draft[name])} placeholder={placeholder} maxLength={1000} onChange={event => setDraft({ ...draft, [name]: event.target.value })} /></Field>;
  const removeItem = () => {
    if (!remove) return;
    if (remove.type === 'plugin') setInstalled(installed.filter(item => item.id !== remove.id));
    if (remove.type === 'mcp') saveItems(p, 'mcps', servers.filter(item => item.id !== remove.id));
    if (remove.type === 'market') saveItems(p, 'markets', markets.filter(item => item.id !== remove.id));
    setStatus(`已移除“${remove.name}”的记录。`); setRemove(null);
  };
  return <div className="integration-settings">
    <div className="integration-intro"><p>管理插件、技能和 MCP</p><div className="integration-actions"><Button onClick={() => setPanel('directory')}>浏览目录</Button><Dropdown label="插件操作" trigger={<Plus size={16} />} align="right" options={[{ label: '添加 MCP 服务器', onSelect: () => { setDraft(newMcp()); setPanel('mcp'); } }, { label: '添加市场', onSelect: () => setPanel('marketplace') }]} /></div></div>
    <div className="integration-tabs" role="tablist" aria-label="管理扩展">{['插件', '应用', 'MCP', '技能', '市场'].map(name => <button key={name} role="tab" aria-selected={tab === name} onClick={() => { setTab(name); setQuery(''); }}>{name}</button>)}</div>
    <div className="integration-toolbar"><SearchBox value={query} onChange={setQuery} placeholder={`搜索${tab}`} /><Button onClick={() => setStatus('列表已刷新。')}><RefreshCw size={14} /><span>刷新</span></Button></div>
    {['插件', '应用', '技能'].includes(tab) && <div className="integration-list">{installed.filter(item => item.category === tab && matches(`${item.name} ${item.description}`, query)).map(item => <div className="integration-item" key={item.id}><span className="integration-item-icon"><Blocks size={20} /></span><button className="integration-item-copy" onClick={() => setDetail(item)}><strong>{item.name}</strong><span>{item.description}</span></button><label className="integration-visually-hidden" htmlFor={`plugin-${item.id}`}>启用 {item.name}</label><Toggle id={`plugin-${item.id}`} checked={item.enabled} onChange={() => setInstalled(installed.map(entry => entry.id === item.id ? { ...entry, enabled: !entry.enabled } : entry))} /><Dropdown label={`${item.name} 的更多操作`} trigger={<MoreHorizontal size={16} />} align="right" options={[{ label: '设置', onSelect: () => setDetail(item) }, { label: '移除', danger: true, onSelect: () => setRemove({ type: 'plugin', id: item.id, name: item.name }) }]} /></div>)}{!installed.some(item => item.category === tab && matches(`${item.name} ${item.description}`, query)) && <Empty><Blocks size={25} /><h3>{query ? '没有匹配的结果' : `未找到${tab}`}</h3><Button onClick={() => setPanel('directory')}>浏览目录</Button></Empty>}</div>}
    {tab === 'MCP' && <><Group title="服务器">{servers.filter(item => matches(item.name, query)).map(server => <PreferenceRow key={server.id} label={server.name} description={server.transport} htmlFor={`mcp-${server.id}`}><Button onClick={() => { saveItems(p, 'mcps', servers.map(item => item.id === server.id ? { ...item, authenticated: !item.authenticated } : item)); }}>{server.authenticated ? '已保存认证设置' : '设置认证'}</Button><Toggle id={`mcp-${server.id}`} checked={server.enabled} onChange={() => saveItems(p, 'mcps', servers.map(item => item.id === server.id ? { ...item, enabled: !item.enabled } : item))} /><Button onClick={() => { setDraft(server); setPanel('mcp'); }}>设置</Button></PreferenceRow>)}{!servers.some(item => matches(item.name, query)) && <Empty>未连接 MCP 服务器</Empty>}<div className="integration-card-footer"><Button onClick={() => { setDraft(newMcp()); setPanel('mcp'); }}><Plus size={14} />添加服务器</Button></div></Group><Group title="MCP Apps"><PreferenceRow label="应用数据" description="清除所有 MCP 应用的网站数据和缓存"><Button onClick={() => setStatus('尚无 MCP 应用缓存。')}>清除所有应用数据</Button></PreferenceRow></Group></>}
    {tab === '市场' && <Group>{matches('内置市场', query) && <PreferenceRow label="内置市场" description="内置市场会自动更新"><span className="integration-muted">自动更新</span></PreferenceRow>}{markets.filter(item => matches(item.name, query)).map(market => <PreferenceRow key={market.id} label={market.name} description="自定义市场"><Button onClick={() => setStatus(`“${market.name}”尚未连接，无法检查更新。`)}>升级</Button><Button danger onClick={() => setRemove({ type: 'market', id: market.id, name: market.name })}>移除</Button></PreferenceRow>)}<div className="integration-card-footer"><Button onClick={() => setPanel('marketplace')}><Plus size={14} />添加市场</Button></div></Group>}
    <p className="integration-status" role="status">{status}</p><Note>插件运行服务尚未连接。此处仅管理配置记录。</Note>
    {panel === 'directory' && <Dialog title="浏览目录" onClose={() => setPanel(null)} className="integration-dialog integration-wide-dialog"><Note>选择要添加的工具。</Note>{directory.map(entry => <PreferenceRow key={entry.id} label={entry.name} description={`${entry.category} · ${entry.description}`}><Button disabled={installed.some(item => item.id === entry.id)} onClick={() => install(entry)}>{installed.some(item => item.id === entry.id) ? '已添加' : '添加'}</Button></PreferenceRow>)}</Dialog>}
    {detail && <Dialog title={detail.name} onClose={() => setDetail(null)} className="integration-dialog"><p>{detail.description}</p><Note>工具服务尚未连接。</Note><Group><PreferenceRow label="状态"><span>{installed.find(item => item.id === detail.id)?.enabled ? '已启用' : '已禁用'}</span></PreferenceRow><PreferenceRow label="来源"><span>内置目录</span></PreferenceRow></Group><div className="integration-dialog-actions"><Button onClick={() => setDetail(null)}>完成</Button></div></Dialog>}
    {panel === 'marketplace' && <Dialog title="添加市场" onClose={() => setPanel(null)} className="integration-dialog"><Note>保存市场记录，仓库连接尚未启用。</Note><Field label="名称"><input value={marketName} onChange={event => setMarketName(event.target.value)} maxLength={80} placeholder="市场名称" /></Field><div className="integration-dialog-actions"><Button onClick={() => setPanel(null)}>取消</Button><Button disabled={!marketName.trim()} onClick={() => { saveItems(p, 'markets', [...markets, { id: crypto.randomUUID(), name: marketName.trim() }]); setMarketName(''); setPanel(null); setTab('市场'); }}>添加</Button></div></Dialog>}
    {panel === 'mcp' && <Dialog title={draft.id ? `更新 ${draft.name} MCP` : '连接自定义 MCP'} onClose={() => setPanel(null)} className="integration-dialog integration-wide-dialog"><Note>服务器连接尚未启用，请勿填写密码、Token 或密钥。</Note>{field('name', '名称', '服务器名称')}<Field label="类型"><select disabled={Boolean(draft.id)} value={draft.transport} onChange={event => setDraft({ ...draft, transport: event.target.value })}><option>STDIO</option><option>Streamable HTTP</option></select></Field>{draft.id && <p className="integration-note">若要更改 MCP 服务器类型，请先卸载。</p>}{draft.transport === 'STDIO' ? <>{field('command', '启动命令', 'example-command')}{field('args', '参数', '每项以空格分隔')}{field('env', '环境变量', 'EXAMPLE=value')}{field('passthrough', '环境变量透传', 'EXAMPLE_NAME')}{field('cwd', '工作目录', '/example/project')}</> : <>{field('url', 'URL', 'https://example.test/mcp')}{field('bearer', 'Bearer token 环境变量名', 'EXAMPLE_TOKEN')}{field('headers', 'Headers', 'X-Client: studio')}{field('envHeaders', '来自环境变量的 Headers', 'X-Example: EXAMPLE_NAME')}</>}<div className="integration-dialog-actions">{draft.id && <Button danger onClick={() => { setPanel(null); setRemove({ type: 'mcp', id: draft.id, name: draft.name }); }}>卸载</Button>}<Button onClick={() => setPanel(null)}>取消</Button><Button disabled={!draft.name.trim() || !(draft.transport === 'STDIO' ? draft.command.trim() : draft.url.trim())} onClick={() => { const server = { ...draft, id: draft.id || crypto.randomUUID(), name: draft.name.trim() }; saveItems(p, 'mcps', [...servers.filter(item => item.id !== server.id), server]); setPanel(null); setTab('MCP'); }}>保存配置</Button></div></Dialog>}
    {remove && <Confirmation title={`移除“${remove.name}”？`} onClose={() => setRemove(null)} onConfirm={removeItem}>这将移除该条记录。{remove.type === 'market' ? '你可以再次添加此市场。' : ''}</Confirmation>}
  </div>;
}

type SavedLogin = { id: string; account: string; site: string; saved: string };
const sampleLogins: SavedLogin[] = [{ id: 'demo-login', account: '个人账户', site: 'example.test', saved: '今天' }, { id: 'demo-work', account: '工作账户', site: 'workspace.example.test', saved: '昨天' }];
function Passwords(p: Props) {
  const [query, setQuery] = useState('');
  const [connect, setConnect] = useState(false);
  const [disconnect, setDisconnect] = useState(false);
  const [remove, setRemove] = useState<SavedLogin | null>(null);
  const [status, setStatus] = useState('');
  const logins = items<SavedLogin>(p, 'passwords', []);
  return <div className="integration-settings"><p className="settings-page-description">管理已保存的网站登录信息</p><Group title="凭据管理器"><PreferenceRow label="1Password" description={enabled(p, 'onepassword') ? '已保存设置 · 未连接' : '未连接'}><Button onClick={() => enabled(p, 'onepassword') ? setDisconnect(true) : setConnect(true)}>{enabled(p, 'onepassword') ? '断开连接' : '设置'}</Button><Button onClick={() => setStatus('连接设置已刷新。')}>刷新</Button></PreferenceRow></Group><section className="integration-password-section"><div className="integration-subheading"><h3>已保存的密码{logins.length ? `（${logins.length}）` : ''}</h3><Button onClick={() => setStatus('密码记录已刷新。')}><RefreshCw size={14} />刷新</Button></div><SearchBox value={query} onChange={setQuery} placeholder="搜索密码" />{logins.filter(item => matches(`${item.account} ${item.site}`, query)).length ? <div className="integration-table-wrap"><table><thead><tr><th>账户</th><th>网站</th><th>保存时间</th><th><span className="integration-visually-hidden">操作</span></th></tr></thead><tbody>{logins.filter(item => matches(`${item.account} ${item.site}`, query)).map(item => <tr key={item.id}><td>{item.account}</td><td>{item.site}</td><td>{item.saved}</td><td><button className="integration-icon-button" aria-label={`移除账户 ${item.account} 在 ${item.site} 上的密码`} onClick={() => setRemove(item)}><Trash2 size={15} /></button></td></tr>)}</tbody></table></div> : <Empty><KeyRound size={24} /><span>{query ? '没有匹配的密码' : '尚未保存任何密码'}</span></Empty>}</section><div className="integration-demo-controls"><Button onClick={() => { saveItems(p, 'passwords', sampleLogins); setQuery(''); }}>载入内置记录</Button><Note>此处仅显示登录信息，不包含密码。</Note></div><p role="status" className="integration-status">{status}</p>
    {connect && <Dialog title="选择密码管理器" onClose={() => setConnect(false)} className="integration-dialog"><div className="integration-provider"><KeyRound size={28} /><strong>1Password</strong><Check size={18} /></div><p className="integration-dialog-description">ChatGPT 请求你登录时，可以使用从 1Password 中选择的登录信息。你可以选择共享哪条登录信息。</p><Note>密码库服务尚未连接。</Note><div className="integration-dialog-actions"><Button onClick={() => setConnect(false)}>取消</Button><Button onClick={() => { p.setValue(key('onepassword'), true); setConnect(false); setStatus('设置已保存，密码库尚未连接。'); }}>保存设置</Button></div></Dialog>}
    {disconnect && <Confirmation title="断开 1Password 连接？" action="断开连接" onClose={() => setDisconnect(false)} onConfirm={() => { p.setValue(key('onepassword'), false); setDisconnect(false); }}>清除当前连接设置。</Confirmation>}
    {remove && <Confirmation title="要删除此密码吗？" action="删除" onClose={() => setRemove(null)} onConfirm={() => { saveItems(p, 'passwords', logins.filter(item => item.id !== remove.id)); setRemove(null); }}>此操作不会让你退出该网站的登录状态。仅移除此处的记录。</Confirmation>}
  </div>;
}

const demoApps = ['Finder', '备忘录', 'Safari', 'Google Chrome', '日历', '信息'];
type ChatPermission = { id: string; name: string; access: string };
function Computer(p: Props) {
  const [page, setPage] = useState('');
  const [addChat, setAddChat] = useState(false);
  const [chatQuery, setChatQuery] = useState('');
  const [chat, setChat] = useState('');
  const [access, setAccess] = useState('始终询问');
  const [remove, setRemove] = useState<{ type: 'app' | 'chat' | 'send' | 'extension'; id: string; name: string } | null>(null);
  const [install, setInstall] = useState('');
  const [moreBrowsers, setMoreBrowsers] = useState(false);
  const readPermissions = items<ChatPermission>(p, 'message.readPermissions', []);
  const sendPermissions = items<string>(p, 'message.sendPermissions', []);
  const allowedApps = items<string>(p, 'computer.allowedApps', []);
  const browserInstalled = (name: string) => enabled(p, `computer.${name}.installed`, name === 'Google Chrome');
  const browserRows = (names: string[]) => names.map(name => <PreferenceRow key={name} label={name} htmlFor={`computer-${name}`} description={name === 'Safari' ? 'Safari 扩展支持即将推出' : browserInstalled(name) ? '已保存设置 · 未安装' : '未安装'}>{name !== 'Safari' && <><Button onClick={() => browserInstalled(name) ? setPage(name) : setInstall(name)}>{browserInstalled(name) ? '管理' : '安装'}</Button>{browserInstalled(name) && <Toggle id={`computer-${name}`} checked={enabled(p, `computer.${name}.enabled`, true)} onChange={() => p.setValue(key(`computer.${name}.enabled`), !enabled(p, `computer.${name}.enabled`, true))} />}</>}</PreferenceRow>);
  const confirmRemove = () => {
    if (!remove) return;
    if (remove.type === 'app') saveItems(p, 'computer.allowedApps', allowedApps.filter(item => item !== remove.id));
    if (remove.type === 'chat') saveItems(p, 'message.readPermissions', readPermissions.filter(item => item.id !== remove.id));
    if (remove.type === 'send') saveItems(p, 'message.sendPermissions', sendPermissions.filter(item => item !== remove.id));
    if (remove.type === 'extension') { p.setValue(key(`computer.${remove.id}.installed`), false); setPage(''); }
    setRemove(null);
  };
  return <div className="integration-settings">
    {page ? <Back title="电脑操控" onClick={() => setPage('')} /> : <p className="settings-page-description">管理 ChatGPT 如何使用你电脑上的其他应用程序</p>}
    {page === '消息' ? <><h3 className="integration-page-title">消息</h3><Group title="读取权限"><LocalSelect p={p} name="message.readPolicy" label="读取方式" options={['默认询问', '默认允许', '允许读取所有聊天']} description={value(p, 'message.readPolicy', '默认询问') === '允许读取所有聊天' ? '已保存的选择（包括“始终不允许”）均不适用' : '读取尚未保存选择的聊天前先询问'} /><div className="integration-subheading"><h4>各聊天的权限</h4><Button onClick={() => { setChat(''); setChatQuery(''); setAddChat(true); }}>添加</Button></div>{readPermissions.map(item => <PreferenceRow key={item.id} label={item.name} htmlFor={`read-${item.id}`}><SelectControl id={`read-${item.id}`} value={item.access} options={['始终允许', '始终询问', '始终不允许']} onChange={next => saveItems(p, 'message.readPermissions', readPermissions.map(entry => entry.id === item.id ? { ...entry, access: next } : entry))} /><button className="integration-icon-button" aria-label={`移除 ${item.name} 的读取权限`} onClick={() => setRemove({ type: 'chat', id: item.id, name: item.name })}><Trash2 size={15} /></button></PreferenceRow>)}{!readPermissions.length && <Empty>暂无</Empty>}</Group><Group title="发送权限"><LocalToggle p={p} name="message.sendAll" label="始终允许向所有聊天发送消息" description="开启后，ChatGPT 可以向任何聊天发送消息，无需你批准消息内容或收件人。" /><div className="integration-subheading"><h4>按聊天授权</h4></div>{sendPermissions.map(name => <PreferenceRow key={name} label={name}><button className="integration-icon-button" aria-label={`移除 ${name}`} onClick={() => setRemove({ type: 'send', id: name, name })}><Trash2 size={15} /></button></PreferenceRow>)}{!sendPermissions.length && <Empty>暂无</Empty>}</Group><div className="integration-demo-controls"><Button onClick={() => saveItems(p, 'message.sendPermissions', ['工作群'])}>载入授权记录</Button></div></> : page ? <><h3 className="integration-page-title">{page}</h3><Group><PreferenceRow label={page} description={browserInstalled(page) ? '已保存设置 · 未安装' : '未安装'}><Button onClick={() => setInstall(page)}>重新安装扩展程序</Button><Button danger onClick={() => setRemove({ type: 'extension', id: page, name: page })}>移除扩展程序</Button></PreferenceRow></Group><BrowserPermissions p={p} prefix={`external.${page}`} /></> : <><Group title="控制"><PreferenceRow label="任意应用" description="允许 ChatGPT 控制你电脑上的应用" htmlFor="integration-computer-use"><Toggle id="integration-computer-use" checked={p.preferences.computerUse} onChange={() => p.updatePreference('computerUse', !p.preferences.computerUse)} /></PreferenceRow>{browserRows(['Google Chrome'])}<PreferenceRow label="更多浏览器" description="为更多浏览器设置扩展程序"><button className="integration-icon-button" aria-label="更多浏览器" aria-expanded={moreBrowsers} onClick={() => setMoreBrowsers(!moreBrowsers)}>{moreBrowsers ? <ChevronDown size={17} /> : <ChevronRight size={17} />}</button></PreferenceRow>{moreBrowsers && browserRows(['Microsoft Edge', 'Safari'])}<PreferenceRow label="消息" description="允许 ChatGPT 读取和发送消息" htmlFor="integration-messages"><Button onClick={() => setPage('消息')}>管理</Button><Toggle id="integration-messages" checked={enabled(p, 'message.enabled')} onChange={() => p.setValue(key('message.enabled'), !enabled(p, 'message.enabled'))} /></PreferenceRow>{['Microsoft Excel', 'Microsoft PowerPoint', 'Microsoft Word'].map(name => <LocalToggle key={name} p={p} name={`computer.${name}`} label={name} description={`允许 ChatGPT 使用 ${name} 加载项以获得更多控制权限`} />)}<LocalToggle p={p} name="computer.locked" label="锁屏操作" description="允许 ChatGPT 在 Mac 锁定时使用此 Mac。" /></Group><Group title="始终允许的应用">{allowedApps.map(name => <PreferenceRow key={name} label={name}><button className="integration-icon-button" aria-label={`移除 ${name}`} onClick={() => setRemove({ type: 'app', id: name, name })}><Trash2 size={15} /></button></PreferenceRow>)}{!allowedApps.length && <Empty>暂无</Empty>}</Group><div className="integration-toolbar integration-sound-select"><SelectControl id="integration-click-sounds" label="电脑操控音效" value={value(p, 'computer.sounds', '为前台点击播放音效')} options={['为前台点击播放音效', '为前台和后台点击播放音效', '不播放音效']} onChange={next => p.setValue(key('computer.sounds'), next)} /><Button onClick={() => saveItems(p, 'computer.allowedApps', ['Finder', '备忘录'])}>载入应用记录</Button></div></>}
    <Note>系统控制服务尚未连接，当前仅保存权限偏好。</Note>
    {install && <Dialog title={`安装 ${install} 扩展程序`} onClose={() => setInstall('')} className="integration-dialog"><p className="integration-dialog-description">扩展安装服务尚未连接，可以先保存浏览器设置。</p><div className="integration-dialog-actions"><Button onClick={() => setInstall('')}>取消</Button><Button onClick={() => { p.setValue(key(`computer.${install}.installed`), true); setInstall(''); }}>保存设置</Button></div></Dialog>}
    {addChat && <Dialog title="添加聊天" onClose={() => setAddChat(false)} className="integration-dialog"><p className="integration-dialog-description">选择是否允许 ChatGPT 使用特定聊天中的消息来回复你的请求</p><SearchBox value={chatQuery} onChange={setChatQuery} placeholder="搜索聊天" /><div className="integration-choice-list">{['工作群', '联系人', '家庭'].filter(name => matches(name, chatQuery)).map(name => <label key={name}><input type="radio" name="demo-chat" checked={chat === name} onChange={() => setChat(name)} /><span>{name}</span></label>)}</div><Field label="读取权限"><select value={access} onChange={event => setAccess(event.target.value)}>{['始终允许', '始终询问', '始终不允许'].map(option => <option key={option}>{option}</option>)}</select></Field><Note>这里没有读取你的真实消息或联系人。</Note><div className="integration-dialog-actions"><Button onClick={() => setAddChat(false)}>取消</Button><Button disabled={!chat} onClick={() => { saveItems(p, 'message.readPermissions', [...readPermissions.filter(item => item.id !== chat), { id: chat, name: chat, access }]); setAddChat(false); }}>添加</Button></div></Dialog>}
    {remove && <Confirmation title={remove.type === 'app' ? `要将“${remove.name}”从始终允许使用的应用中移除吗？` : `移除“${remove.name}”的${remove.type === 'chat' ? '读取权限' : remove.type === 'send' ? '发送权限' : '扩展程序'}？`} onClose={() => setRemove(null)} onConfirm={confirmRemove}>{remove.type === 'app' ? `ChatGPT 会在下一次电脑操控会话中请求使用“${remove.name}”。` : '此操作仅更新当前设置。'}</Confirmation>}
  </div>;
}

type Activity = { id: string; title: string; app: string; minutes: number; time: string; text: string };
const sampleActivities: Activity[] = [
  { id: 'recent', title: '整理发布计划', app: '备忘录', minutes: 3, time: '14:20 – 14:32', text: '整理下一阶段的任务，并记录需要跟进的事项。' },
  { id: 'research', title: '查看设计参考', app: 'Google Chrome', minutes: 40, time: '13:40 – 14:02', text: '比较设置页面中的分组、导航和交互流程。' },
  { id: 'morning', title: '浏览项目资料', app: 'Finder', minutes: 300, time: '09:10 – 09:25', text: '查看项目资料并整理文档。' },
];
function HistorySettings(p: Props) {
  const [dialog, setDialog] = useState<'consent' | 'memory' | 'permissions' | null>(null);
  const [customizingFirst, setCustomizingFirst] = useState(false);
  const [confirm, setConfirm] = useState<{ title: string; range?: number; id?: string } | null>(null);
  const [appQuery, setAppQuery] = useState('');
  const [appMode, setAppMode] = useState('排除这些应用');
  const [siteMode, setSiteMode] = useState('排除这些网站');
  const [selectedApps, setSelectedApps] = useState<string[]>([]);
  const [sites, setSites] = useState<string[]>([]);
  const [domain, setDomain] = useState('');
  const [domainError, setDomainError] = useState('');
  const records = items<Activity>(p, 'history.records', []);
  const excluded = items<string>(p, 'history.apps', []);
  const appIsIncluded = (app: string) => value(p, 'history.appMode', '排除这些应用') === '仅包含这些应用' ? excluded.includes(app) : !excluded.includes(app);
  const selectedCount = excluded.length + items<string>(p, 'history.sites', []).length;
  const beginEnable = () => { if (enabled(p, 'history.memories')) { p.updatePreference('computerHistory', true); setDialog(null); } else setDialog('memory'); };
  const openPermissions = (first = false) => { setCustomizingFirst(first); setSelectedApps(excluded); setSites(items<string>(p, 'history.sites', [])); setAppMode(value(p, 'history.appMode', '排除这些应用')); setSiteMode(value(p, 'history.siteMode', '排除这些网站')); setAppQuery(''); setDomain(''); setDomainError(''); setDialog('permissions'); };
  const clear = () => { if (!confirm) return; saveItems(p, 'history.records', confirm.id ? records.filter(item => item.id !== confirm.id) : records.filter(item => item.minutes > (confirm.range ?? Infinity))); setConfirm(null); };
  return <div className="integration-settings">
    {!p.preferences.computerHistory ? <div className="integration-history-hero"><div><Clock3 size={27} /><h3>让 ChatGPT 关注你的工作</h3><p>ChatGPT 可以总结你在所用应用和网站中的活动，且绝不会录制你的屏幕或音频。</p><p>询问你之前正在处理的事项，无需再次解释一切即可获得帮助，或发现自动化重复任务的机会。</p><Button onClick={() => setDialog('consent')}>开启</Button></div><div className="integration-history-example" aria-label="电脑历史记录用法"><span className="integration-muted">使用方式</span><div className="integration-example-user">我之前看到的规划文档在哪里？</div><p>你今天上午在 Google Docs 中查看了第四季度发布计划。</p><span className="integration-example-link">Q4 Launch Planning</span></div></div> : <><Group><PreferenceRow label="电脑历史记录" htmlFor="integration-history-enabled" description={enabled(p, 'history.paused') ? '记录偏好：已暂停' : '记录偏好：已开启'}><Button onClick={() => p.setValue(key('history.paused'), !enabled(p, 'history.paused'))}>{enabled(p, 'history.paused') ? '继续' : '暂停'}</Button><Toggle id="integration-history-enabled" checked={p.preferences.computerHistory} onChange={() => p.updatePreference('computerHistory', false)} /></PreferenceRow><LocalToggle p={p} name="history.indicator" label="在菜单栏中显示指示器" fallback /><PreferenceRow label="权限" description="选择要在电脑历史记录中排除或纳入的应用和网站"><Button onClick={() => openPermissions()}>{selectedCount ? `已选中 ${selectedCount} 项` : '选择'}</Button></PreferenceRow></Group><div className="integration-subheading"><h3>历史记录</h3><Dropdown label="清除历史记录" trigger={<>清除历史记录<ChevronDown size={13} /></>} align="right" options={[{ label: '清除最近 10 分钟', onSelect: () => setConfirm({ title: '清除最近 10 分钟的记录？', range: 10 }) }, { label: '清除过去一小时', onSelect: () => setConfirm({ title: '清除过去一小时的记录？', range: 60 }) }, { label: '清除最近一天', onSelect: () => setConfirm({ title: '清除最近一天的记录？', range: 1440 }) }, { label: '清除全部', danger: true, onSelect: () => setConfirm({ title: '清除所有历史记录？', range: Infinity }) }]} /></div><p className="integration-note">ChatGPT 会记录你电脑活动的文本摘要。你可以通过删除单条记录或清除最近历史记录，来控制 ChatGPT 可以引用的内容。</p>{records.length ? <div className="integration-timeline"><h4>今天</h4>{records.map(record => <article key={record.id}><span className="integration-timeline-dot" /><div className="integration-subheading"><span className="integration-muted">{record.time}</span><Dropdown label={`${record.title} 的操作`} trigger={<MoreHorizontal size={16} />} align="right" options={[{ label: appIsIncluded(record.app) ? `从未来历史记录中排除 ${record.app}` : `在未来历史记录中纳入 ${record.app}`, onSelect: () => saveItems(p, 'history.apps', excluded.includes(record.app) ? excluded.filter(app => app !== record.app) : [...excluded, record.app]) }, { label: '删除', danger: true, onSelect: () => setConfirm({ title: '删除此历史记录项？', id: record.id }) }]} /></div><h4>{record.title}</h4><p>{record.text}</p><span className="integration-badge">{record.app}</span></article>)}</div> : <Empty><Clock3 size={25} /><span>暂无电脑历史记录</span></Empty>}</>}
    <div className="integration-demo-controls"><Button onClick={() => saveItems(p, 'history.records', sampleActivities)}>载入内置记录</Button><Note>电脑历史采集服务尚未连接。</Note></div>
    {dialog === 'consent' && <Dialog title="一切由你掌控。" onClose={() => setDialog(null)} className="integration-dialog"><div className="integration-dialog-copy"><p>你可以随时暂停或清除历史记录，并管理其中包含的应用。</p><p>建议暂停记录或将健康、财务等敏感应用排除在历史记录之外。</p><p>你还同意，在与他人交流期间（例如使用视频会议或短信应用时），暂停电脑历史记录，除非事先获得对方明确同意。</p></div><Note>本次仅预览设置流程，不会开始记录。</Note><div className="integration-dialog-actions"><Button onClick={() => setDialog(null)}>取消</Button><Button onClick={() => openPermissions(true)}>自定义应用</Button><Button onClick={() => { saveItems(p, 'history.apps', []); saveItems(p, 'history.sites', []); p.setValue(key('history.appMode'), '排除这些应用'); p.setValue(key('history.siteMode'), '排除这些网站'); beginEnable(); }}>允许所有应用</Button></div></Dialog>}
    {dialog === 'memory' && <Dialog title="开启记忆以使用电脑历史记录？" onClose={() => setDialog(null)} className="integration-dialog"><p className="integration-dialog-description">计算机历史需要开启记忆，以便 ChatGPT 记住你在不同任务中的活动。开启后，ChatGPT 还可以根据你的聊天生成记忆，并在未来的聊天中使用。</p><Note>记忆与历史采集服务尚未连接，仅保存偏好。</Note><div className="integration-dialog-actions"><Button onClick={() => setDialog(null)}>取消</Button><Button onClick={() => { p.setValue(key('history.memories'), true); p.updatePreference('computerHistory', true); setDialog(null); }}>开启记忆</Button></div></Dialog>}
    {dialog === 'permissions' && <Dialog title="电脑历史记录权限" onClose={() => setDialog(null)} className="integration-dialog integration-wide-dialog"><Field label="应用"><select value={appMode} onChange={event => setAppMode(event.target.value)}><option>排除这些应用</option><option>仅包含这些应用</option></select></Field><SearchBox value={appQuery} onChange={setAppQuery} placeholder="搜索应用" /><div className="integration-choice-list integration-app-grid">{demoApps.filter(name => matches(name, appQuery)).map(name => <label key={name}><input type="checkbox" checked={selectedApps.includes(name)} onChange={() => setSelectedApps(selectedApps.includes(name) ? selectedApps.filter(item => item !== name) : [...selectedApps, name])} /><Monitor size={15} /><span>{name}</span></label>)}</div><Field label="网站"><select value={siteMode} onChange={event => setSiteMode(event.target.value)}><option>排除这些网站</option><option>仅包含这些网站</option></select></Field>{sites.map(site => <div className="integration-subheading" key={site}><span>{site}</span><button className="integration-icon-button" aria-label={`移除 ${site}`} onClick={() => setSites(sites.filter(item => item !== site))}><Trash2 size={14} /></button></div>)}<div className="integration-inline-form"><input aria-label="网站域名" placeholder="example.com" value={domain} maxLength={253} onChange={event => { setDomain(event.target.value); setDomainError(''); }} /><Button onClick={() => { const next = domain.trim().toLowerCase(); if (!/^(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,}$/i.test(next)) { setDomainError('请输入域名，例如 example.com。'); return; } setSites([...new Set([...sites, next])]); setDomain(''); }}>添加网站</Button></div>{domainError && <p className="integration-danger" role="alert">{domainError}</p>}<Note>私密模式下的网页浏览活动不包含在电脑历史记录中。</Note><div className="integration-dialog-actions"><Button onClick={() => setDialog(null)}>取消</Button><Button onClick={() => { saveItems(p, 'history.apps', selectedApps); saveItems(p, 'history.sites', sites); p.setValue(key('history.appMode'), appMode); p.setValue(key('history.siteMode'), siteMode); customizingFirst ? beginEnable() : setDialog(null); }}>{customizingFirst ? '继续' : '完成'}</Button></div></Dialog>}
    {confirm && <Confirmation title={confirm.title} action={confirm.id ? '删除' : '清除'} onClose={() => setConfirm(null)} onConfirm={clear}>你的操作以及由此创建的任何记忆都将被删除。此操作无法撤消。仅删除此页中的记录。</Confirmation>}
  </div>;
}

function Snapshots(p: Props) {
  const [step, setStep] = useState(0);
  const destination = value(p, 'snapshot.destination', '自动');
  const hotkey = value(p, 'snapshot.hotkey', p.preferences.appSnapshots ? '⌘ + ⌘' : '无');
  return <div className="integration-settings"><div className="integration-snapshot-hero"><span className="integration-hero-icon"><Monitor size={25} /></span><div><h3>截取应用快照，向 ChatGPT 展示最前面的窗口</h3><p>应用快照包含视觉和文本内容，包括滚动到屏幕外的文本。</p></div></div><div className="integration-snapshot-grid"><Group><PreferenceRow label="快捷键" description={hotkey === '无' ? undefined : `同时按下两个 ${hotkey.split(' + ')[0]} 键`} htmlFor="integration-snapshot-hotkey"><SelectControl id="integration-snapshot-hotkey" value={hotkey} options={['⌘ + ⌘', '⌥ + ⌥', '⇧ + ⇧', '无']} onChange={next => { p.setValue(key('snapshot.hotkey'), next); p.updatePreference('appSnapshots', next !== '无'); }} /></PreferenceRow><LocalSelect p={p} name="snapshot.destination" label="应用快照发送目标" description={destination === '自动' ? '如果当前聊天最近使用过，则使用当前聊天；否则开始新聊天' : destination === '当前聊天' ? '始终使用当前聊天' : '始终开始新聊天'} options={['自动', '当前聊天', '新聊天']} /><LocalToggle p={p} name="snapshot.mini" label="使用 Mini（当其可见时）" description="Mini 不可见时，Appshots 会采用自动路由" fallback /><LocalToggle p={p} name="snapshot.sound" label="播放音效" fallback /></Group><div className="integration-snapshot-demo" aria-label="应用快照流程示意"><div className="integration-demo-window"><span className="integration-demo-dots"><i /><i /><i /></span><div className="integration-demo-lines"><b /><span /><span /><span /></div>{step > 0 && <div className="integration-capture-frame"><Check size={20} /></div>}</div><div className="integration-demo-chat"><span>ChatGPT</span>{step > 1 ? <div className="integration-demo-attachment"><Monitor size={15} />窗口内容</div> : <div className="integration-demo-placeholder">询问任何问题</div>}</div><Button onClick={() => setStep((step + 1) % 3)}><Play size={13} />{step === 0 ? '预览流程' : step === 1 ? '发送到聊天' : '再次预览'}</Button><p>{['显示最前面的窗口', '捕获视觉和文本内容', `发送到${destination === '自动' ? '最近的聊天' : destination}`][step]}</p><span className="integration-demo-caption">流程示意 · 未捕获实际窗口</span></div></div><Note>只保存界面偏好，不注册全局快捷键，不捕获窗口或播放系统音效。</Note></div>;
}

function BrowserPermissions({ p, prefix = 'browser', openSites }: { p: Props; prefix?: string; openSites?: () => void }) {
  return <><Group title="权限">{openSites && <PreferenceRow label="网站设置" description="管理内置浏览器中的摄像头和麦克风权限"><Button onClick={openSites}>管理</Button></PreferenceRow>}<LocalSelect p={p} name={`${prefix}.historyAccess`} label="历史记录" description="选择 ChatGPT 在访问你的浏览器历史记录前是否需要请求批准" options={['始终询问', '始终允许', '禁用']} /><LocalToggle p={p} name={`${prefix}.webMcp`} label="启用站点工具" description="允许 ChatGPT 发现并调用网站公开的站点工具，包括 WebMCP" /></Group><Group title="开发者模式"><LocalToggle p={p} name={`${prefix}.cdp`} label="启用完整 CDP 访问权限" description="完整 CDP 访问权限可检查并控制敏感的浏览器内部功能。浏览器控制服务尚未连接。" /></Group></>;
}
type BrowserVisit = { id: string; title: string; url: string; source: string; minutes: number; time: string };
type BrowserDownload = { id: string; name: string; site: string; status: '已下载' | '下载中' | '已暂停' | '已停止'; minutes: number };
const sampleVisits: BrowserVisit[] = [
  { id: 'visit-1', title: '项目说明', url: 'https://example.test/project', source: '智能体', minutes: 10, time: '14:32' },
  { id: 'visit-2', title: '界面设计参考', url: 'https://example.test/design', source: '其他', minutes: 90, time: '13:12' },
  { id: 'visit-3', title: '文档', url: 'https://docs.example.test', source: '智能体', minutes: 1500, time: '昨天' },
];
const sampleDownloads: BrowserDownload[] = [{ id: 'download-1', name: '项目说明.pdf', site: 'example.test', status: '已下载', minutes: 15 }, { id: 'download-2', name: '界面素材.zip', site: 'example.test', status: '下载中', minutes: 30 }];
const browsingTypes = ['浏览历史记录', 'Cookie 和站点数据', '缓存的图片和文件', '下载历史记录', '自动填充表单数据', '站点设置'];
const clearRanges: Record<string, number> = { '过去 1 小时': 60, '过去 24 小时': 1440, '过去 7 天': 10080, '过去 4 周': 40320, '全部时间': Infinity };

function Browser(p: Props) {
  const [page, setPage] = useState('');
  const [query, setQuery] = useState('');
  const [source, setSource] = useState('全部');
  const [selected, setSelected] = useState<string[]>([]);
  const [dialog, setDialog] = useState<'clear' | 'folder' | 'import' | 'contact' | null>(null);
  const [showClear, setShowClear] = useState(false);
  const [clearRange, setClearRange] = useState('全部时间');
  const [clearTypes, setClearTypes] = useState<string[]>(browsingTypes.slice(0, 4));
  const [folder, setFolder] = useState('系统下载文件夹');
  const [importBrowser, setImportBrowser] = useState('Google Chrome');
  const [importTypes, setImportTypes] = useState(['浏览历史记录']);
  const [info, setInfo] = useState<{ title: string; content: string } | null>(null);
  const [status, setStatus] = useState('');
  const [contactName, setContactName] = useState('');
  const [contactAddress, setContactAddress] = useState('');
  const visits = items<BrowserVisit>(p, 'browser.visits', []);
  const downloads = items<BrowserDownload>(p, 'browser.downloads', []);
  const contacts = items<{ id: string; name: string; address: string }>(p, 'browser.contacts', []);
  const extensions = items<{ id: string; name: string; enabled: boolean }>(p, 'browser.extensions', []);
  const browserPasswords = items<SavedLogin>(p, 'browser.passwords', []);
  const [passwordToDelete, setPasswordToDelete] = useState<SavedLogin | null>(null);
  const filteredVisits = visits.filter(item => matches(`${item.title} ${item.url}`, query) && (source === '全部' || item.source === source));
  const go = (next: string) => { setPage(next); setQuery(''); setSelected([]); setStatus(''); };
  const showClearDialog = (types = browsingTypes.slice(0, 4)) => { setClearTypes(types); setClearRange('全部时间'); setDialog('clear'); };
  const manage = (title: string, description: string) => <PreferenceRow label={title} description={description}><Button onClick={() => go(title)}>管理</Button></PreferenceRow>;
  const removeVisits = (ids: string[]) => { saveItems(p, 'browser.visits', visits.filter(item => !ids.includes(item.id))); setSelected(selected.filter(id => !ids.includes(id))); };
  const updateDownload = (id: string, next: BrowserDownload['status']) => saveItems(p, 'browser.downloads', downloads.map(item => item.id === id ? { ...item, status: next } : item));
  const clearData = () => {
    const minutes = clearRanges[clearRange];
    if (clearTypes.includes('浏览历史记录')) saveItems(p, 'browser.visits', visits.filter(item => item.minutes > minutes));
    if (clearTypes.includes('下载历史记录')) saveItems(p, 'browser.downloads', downloads.filter(item => item.minutes > minutes));
    if (clearTypes.includes('自动填充表单数据')) saveItems(p, 'browser.contacts', []);
    if (clearTypes.includes('站点设置')) { p.setValue(key('browser.camera'), '询问'); p.setValue(key('browser.microphone'), '询问'); }
    setSelected([]); setDialog(null); setStatus(`已清除${clearRange}的所选记录。`);
  };
  return <div className="integration-settings">
    {page ? <><Back title="浏览器" onClick={() => go('')} /><h3 className="integration-page-title">{page}</h3></> : <p className="settings-page-description">管理你的 Browser Use 偏好设置和网站访问权限。</p>}
    {!page && <><Group><PreferenceRow label="浏览器" description="让 ChatGPT 控制内置浏览器" htmlFor="integration-browser-enabled"><Toggle id="integration-browser-enabled" checked={p.preferences.browserConnection} onChange={() => p.updatePreference('browserConnection', !p.preferences.browserConnection)} /></PreferenceRow></Group><div className="integration-group-heading"><h3>常规</h3><Button onClick={() => setDialog('import')}>导入…</Button></div><Group><LocalSelect p={p} name="browser.links" label="网页 URL 和链接打开位置" options={['ChatGPT', '默认浏览器']} /><LocalSelect p={p} name="browser.localLinks" label="本地 URL 打开位置" description="本地开发站点默认打开位置" options={['ChatGPT', '默认浏览器']} /><LocalToggle p={p} name="browser.fullUrl" label="显示完整网址" description="在地址栏中显示路径、查询参数和片段" /><PreferenceRow label="浏览数据" description="清除应用内浏览器中的浏览历史记录、网站数据、缓存和下载历史记录"><Button onClick={() => showClearDialog()}>清除浏览数据</Button><button className="integration-icon-button" aria-label={showClear ? '隐藏各个浏览数据选项' : '显示各个浏览数据选项'} aria-expanded={showClear} onClick={() => setShowClear(!showClear)}>{showClear ? <ChevronDown size={14} /> : <ChevronRight size={14} />}</button></PreferenceRow>{showClear && browsingTypes.slice(0, 4).map(name => <PreferenceRow key={name} label={name}><Button onClick={() => showClearDialog([name])}>删除</Button></PreferenceRow>)}{manage('浏览历史', '查看和管理在内置浏览器中访问过的页面')}<LocalSelect p={p} name="browser.annotations" label="批注截图" description="截图可帮助 ChatGPT 更好地理解和处理评论，但会增加套餐用量" options={['始终包含', '仅限拖拽选中区域']} /></Group><Group title="自动填充和密码">{manage('密码管理器', '添加、删除和编辑已保存的密码')}{manage('联系信息', '添加、删除和编辑已保存的地址、电话号码和电子邮箱地址')}</Group><Group title="扩展程序">{manage('扩展程序管理器', '安装、移除和配置浏览器扩展程序')}</Group><Group title="下载"><PreferenceRow label="位置" description={value(p, 'browser.folder', '系统下载文件夹')}><Button onClick={() => { setFolder(value(p, 'browser.folder', '系统下载文件夹')); setDialog('folder'); }}>更改</Button>{value(p, 'browser.folder', '系统下载文件夹') !== '系统下载文件夹' && <Button onClick={() => p.setValue(key('browser.folder'), '系统下载文件夹')}>重置</Button>}</PreferenceRow><LocalToggle p={p} name="browser.askDownload" label="下载前询问保存位置" description="对在内置浏览器中发起的下载显示保存对话框" />{manage('下载历史记录', '查看和管理从内置浏览器下载的文件')}</Group><BrowserPermissions p={p} openSites={() => go('网站设置')} /></>}
    {page === '浏览历史' && <><div className="integration-toolbar"><SearchBox value={query} onChange={setQuery} placeholder="搜索浏览历史" /><SelectControl id="integration-history-filter" label="筛选浏览历史记录" value={source} options={['全部', '智能体', '其他']} onChange={setSource} /></div><div className="integration-subheading"><span>全部历史记录</span><div className="integration-actions">{selected.length > 0 && <Button onClick={() => removeVisits(selected)}>移除所选项（{selected.length}）</Button>}<Button onClick={() => showClearDialog()}>清除浏览数据</Button></div></div>{filteredVisits.length ? <div className="integration-list">{filteredVisits.map(visit => <div className="integration-item" key={visit.id}><input aria-label={`选择 ${visit.title}`} type="checkbox" checked={selected.includes(visit.id)} onChange={() => setSelected(selected.includes(visit.id) ? selected.filter(id => id !== visit.id) : [...selected, visit.id])} /><Globe size={18} /><button className="integration-item-copy" onClick={() => setInfo({ title: visit.title, content: `页面地址：${visit.url}。未打开网页。` })}><strong>{visit.title}</strong><span>{visit.url}</span></button><span className="integration-muted">{visit.time}</span>{visit.source === '智能体' && <span className="integration-badge">智能体</span>}<Dropdown label={`${visit.title} 的操作`} trigger={<MoreHorizontal size={16} />} align="right" options={[{ label: '打开页面', onSelect: () => setInfo({ title: visit.title, content: `页面地址：${visit.url}。未打开网页。` }) }, { label: '从历史记录中移除', danger: true, onSelect: () => removeVisits([visit.id]) }]} /></div>)}</div> : <Empty><Clock3 size={24} /><span>{query ? '没有匹配的页面' : source === '全部' ? '暂无浏览记录' : `暂无${source}访问记录`}</span><p>在内置浏览器中访问过的页面将显示在此处</p></Empty>}<div className="integration-demo-controls"><Button onClick={() => { saveItems(p, 'browser.visits', sampleVisits); setQuery(''); }}>载入内置记录</Button></div></>}
    {page === '下载历史记录' && <><div className="integration-toolbar"><SearchBox value={query} onChange={setQuery} placeholder="搜索下载历史记录" /><Button disabled={!downloads.length} onClick={() => showClearDialog(['下载历史记录'])}>清除全部</Button></div>{downloads.filter(item => matches(`${item.name} ${item.site}`, query)).map(item => <div className="integration-item" key={item.id}><span className="integration-item-icon"><Download size={20} /></span><div className="integration-item-copy"><strong>{item.name}</strong><span>{item.site} · {item.status}</span>{item.status === '下载中' && <progress value="42" max="100" aria-label={`${item.name} 下载进度`} />}</div>{item.status === '下载中' || item.status === '已暂停' ? <Button onClick={() => updateDownload(item.id, item.status === '下载中' ? '已暂停' : '下载中')}>{item.status === '下载中' ? '暂停' : '继续'}</Button> : <Button onClick={() => setInfo({ title: item.name, content: '此记录尚未关联文件。' })}>打开</Button>}<Dropdown label={`${item.name} 的下载操作`} trigger={<MoreHorizontal size={16} />} align="right" options={[...(item.status === '下载中' || item.status === '已暂停' ? [{ label: '取消下载', onSelect: () => updateDownload(item.id, '已停止') }] : []), { label: '从下载历史记录中移除', onSelect: () => saveItems(p, 'browser.downloads', downloads.filter(record => record.id !== item.id)) }]} /></div>)}{!downloads.some(item => matches(`${item.name} ${item.site}`, query)) && <Empty><Download size={25} /><span>{query ? '没有匹配的下载项' : '暂无下载内容'}</span></Empty>}<div className="integration-demo-controls"><Button onClick={() => saveItems(p, 'browser.downloads', sampleDownloads)}>载入内置记录</Button></div></>}
    {page === '网站设置' && <Group><LocalSelect p={p} name="browser.camera" label="摄像头" options={['询问', '禁止', '允许']} /><LocalSelect p={p} name="browser.microphone" label="麦克风" options={['询问', '禁止', '允许']} /></Group>}
    {page === '密码管理器' && <><SearchBox value={query} onChange={setQuery} placeholder="搜索密码" /><Group>{browserPasswords.filter(item => matches(`${item.site} ${item.account}`, query)).map(login => <PreferenceRow key={login.id} label={login.site} description={login.account}><Button danger onClick={() => setPasswordToDelete(login)}>删除</Button></PreferenceRow>)}{!browserPasswords.some(item => matches(`${item.site} ${item.account}`, query)) && <Empty>没有已保存的密码</Empty>}</Group><div className="integration-demo-controls"><Button onClick={() => saveItems(p, 'browser.passwords', sampleLogins)}>载入内置记录</Button></div><Note>密码管理服务尚未连接，此处仅管理登录记录。</Note></>}
    {page === '联系信息' && <><div className="integration-subheading"><span>已保存的联系信息</span><Button onClick={() => { setContactName('联系人'); setContactAddress('地址'); setDialog('contact'); }}>添加地址</Button></div><Group>{contacts.map(contact => <PreferenceRow key={contact.id} label={contact.name} description={contact.address}><Button danger onClick={() => saveItems(p, 'browser.contacts', contacts.filter(item => item.id !== contact.id))}>删除</Button></PreferenceRow>)}{!contacts.length && <Empty>暂无联系信息</Empty>}</Group></>}
    {page === '扩展程序管理器' && <><Group>{extensions.map(extension => <PreferenceRow key={extension.id} label={extension.name} description="扩展配置 · 未安装" htmlFor={`browser-extension-${extension.id}`}><Toggle id={`browser-extension-${extension.id}`} checked={extension.enabled} onChange={() => saveItems(p, 'browser.extensions', extensions.map(item => item.id === extension.id ? { ...item, enabled: !item.enabled } : item))} /><Button danger onClick={() => saveItems(p, 'browser.extensions', extensions.filter(item => item.id !== extension.id))}>移除</Button></PreferenceRow>)}{!extensions.length && <Empty>暂无扩展程序</Empty>}</Group><div className="integration-demo-controls"><Button onClick={() => saveItems(p, 'browser.extensions', [{ id: 'demo-extension', name: '浏览助手', enabled: true }])}>添加扩展记录</Button></div></>}
    <p className="integration-status" role="status">{status}</p><Note>浏览器数据服务尚未连接。</Note>
    {dialog === 'clear' && <Dialog title="清除浏览数据" onClose={() => setDialog(null)} className="integration-dialog"><Field label="时间范围"><select value={clearRange} onChange={event => setClearRange(event.target.value)}>{Object.keys(clearRanges).map(range => <option key={range}>{range}</option>)}</select></Field><div className="integration-choice-list">{browsingTypes.map(type => <label key={type}><input type="checkbox" checked={clearTypes.includes(type)} onChange={() => setClearTypes(clearTypes.includes(type) ? clearTypes.filter(item => item !== type) : [...clearTypes, type])} /><span>{type}</span></label>)}</div><Note>仅清除此页中的记录。</Note><div className="integration-dialog-actions"><Button onClick={() => setDialog(null)}>取消</Button><Button danger disabled={!clearTypes.length} onClick={clearData}>删除数据</Button></div></Dialog>}
    {dialog === 'folder' && <Dialog title="下载位置" onClose={() => setDialog(null)} className="integration-dialog"><Field label="选择位置"><select value={folder} onChange={event => setFolder(event.target.value)}>{['系统下载文件夹', '~/Desktop', '~/Documents'].map(path => <option key={path}>{path}</option>)}</select></Field><Note>仅保存路径设置。文件夹选择服务尚未连接。</Note><div className="integration-dialog-actions"><Button onClick={() => setDialog(null)}>取消</Button><Button onClick={() => { p.setValue(key('browser.folder'), folder); setDialog(null); }}>选择</Button></div></Dialog>}
    {dialog === 'import' && <Dialog title="导入浏览器数据" onClose={() => setDialog(null)} className="integration-dialog"><Field label="浏览器"><select value={importBrowser} onChange={event => setImportBrowser(event.target.value)}><option>Google Chrome</option><option>Microsoft Edge</option></select></Field><div className="integration-choice-list">{['浏览历史记录', '联系信息'].map(type => <label key={type}><input type="checkbox" checked={importTypes.includes(type)} onChange={() => setImportTypes(importTypes.includes(type) ? importTypes.filter(item => item !== type) : [...importTypes, type])} /><span>{type}</span></label>)}</div><Note>浏览器数据服务尚未连接，仅添加内置内容记录。</Note><div className="integration-dialog-actions"><Button onClick={() => setDialog(null)}>取消</Button><Button disabled={!importTypes.length} onClick={() => { if (importTypes.includes('浏览历史记录')) saveItems(p, 'browser.visits', [...visits.filter(item => !sampleVisits.some(sample => sample.id === item.id)), ...sampleVisits]); if (importTypes.includes('联系信息')) saveItems(p, 'browser.contacts', [...contacts.filter(item => item.id !== 'import-demo'), { id: 'import-demo', name: '导入联系人', address: '地址' }]); setDialog(null); setStatus(`已添加 ${importBrowser} 的内容记录。`); }}>添加记录</Button></div></Dialog>}
    {dialog === 'contact' && <Dialog title="添加联系信息" onClose={() => setDialog(null)} className="integration-dialog"><Field label="显示名称"><input value={contactName} maxLength={80} onChange={event => setContactName(event.target.value)} /></Field><Field label="地址"><input value={contactAddress} maxLength={250} onChange={event => setContactAddress(event.target.value)} /></Field><Note>联系信息仅保留在本次会话。</Note><div className="integration-dialog-actions"><Button onClick={() => setDialog(null)}>取消</Button><Button disabled={!contactName.trim()} onClick={() => { saveItems(p, 'browser.contacts', [...contacts, { id: crypto.randomUUID(), name: contactName.trim(), address: contactAddress.trim() }]); setDialog(null); }}>保存</Button></div></Dialog>}
    {info && <Dialog title={info.title} onClose={() => setInfo(null)} className="integration-dialog"><p className="integration-dialog-description">{info.content}</p><div className="integration-dialog-actions"><Button onClick={() => setInfo(null)}>完成</Button></div></Dialog>}
    {passwordToDelete && <Confirmation title="删除此密码记录？" action="删除" onClose={() => setPasswordToDelete(null)} onConfirm={() => { saveItems(p, 'browser.passwords', browserPasswords.filter(item => item.id !== passwordToDelete.id)); setPasswordToDelete(null); }}>这将移除浏览器密码管理器中的记录，不影响集成组的“密码”列表。</Confirmation>}
  </div>;
}

export function IntegrationSettings(props: SettingsSectionProps) {
  switch (props.section) {
    case 'plugins': return <Plugins {...props} />;
    case 'passwords': return <Passwords {...props} />;
    case 'computer': return <Computer {...props} />;
    case 'history': return <HistorySettings {...props} />;
    case 'snapshots': return <Snapshots {...props} />;
    case 'browser': return <Browser {...props} />;
    default: return null;
  }
}
